e&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage.html#RAGESANSPEUR&quot; title=&quot;Les pouvoirs de rage du barbare&quot;&gt;Rage sans peur&lt;/a&gt;&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;(EXT)&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td CLASS=&quot;gauche&quot;&gt;Barbare&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;Greater Rage&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html#RAGEDEGRANDBERSERKER&quot; title=&quot;Le barbare&quot;&gt;Rage de grand berserker&lt;/a&gt;&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;(EXT)&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td CLASS=&quot;gauche&quot;&gt;Barbare&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;Guarded Stance&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage.html#POSTUREDEFENSIVE&quot; title=&quot;Les pouvoirs de rage du barbare&quot;&gt;Posture d&#233;fensive&lt;/a&gt;&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;(EXT)&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td CLASS=&quot;gauche&quot;&gt;Barbare&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;Improved Uncanny Dodge &lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html#ESQUIVEINSTICTIVESUPERIEURE&quot; title=&quot;Le barbare&quot;&gt;Esquive instinctive sup&#233;rieure&lt;/a&gt;&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;(EXT)&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td CLASS=&quot;gauche&quot;&gt;Barbare&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;Increased Damage Reduction&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-De-Rage.html#REDUCTIONDEDEGATSACCRUE&quot; title=&quot;Les pouvoirs de rage du barbare&quot;&gt;R&#233;duction de d&#233;g&#226;ts accrue&lt;/a&gt;&lt;/td&gt;&lt;td CLASS=&quot;gauche&quot;&gt;(EXT)&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td CLASS=&quot;gauche&quot;&gt;Barbare&lt;/td&gt;&lt;td CLASS=&quot;ga